CREATE TABLE reading_preference (id UUID PRIMARY KEY DEFAULT uuid_v7(),owner_id UUID NOT NULL,scope VARCHAR(16) NOT NULL,reading_kind VARCHAR(24),work_id UUID,settings JSONB NOT NULL DEFAULT '{}'::jsonb,updated_at TIMESTAMPTZ NOT NULL DEFAULT current_timestamp,version BIGINT NOT NULL DEFAULT 0,CHECK(scope IN ('GLOBAL','KIND','WORK')),CHECK((scope='GLOBAL' AND reading_kind IS NULL AND work_id IS NULL) OR (scope='KIND' AND reading_kind IS NOT NULL AND work_id IS NULL) OR (scope='WORK' AND work_id IS NOT NULL)),FOREIGN KEY(work_id) REFERENCES reading_work(id),UNIQUE(owner_id,scope,reading_kind,work_id));
